namespace private_input::activity {
std::wstring pipeName(const std::wstring&suffix){HANDLE token=nullptr;if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&token))return {};DWORD n=0;GetTokenInformation(token,TokenUser,nullptr,0,&n);std::string storage(n,'\0');if(!GetTokenInformation(token,TokenUser,storage.data(),n,&n)){CloseHandle(token);return {};}CloseHandle(token);LPWSTR sid=nullptr;if(!ConvertSidToStringSidW(reinterpret_cast<TOKEN_USER*>(storage.data())->User.Sid,&sid))return {};DWORD session=0;ProcessIdToSessionId(GetCurrentProcessId(),&session);std::wstring name=L"\\\\.\\pipe\\LingheInput.Activity."+std::wstring(sid)+L"."+std::to_wstring(session);LocalFree(sid);if(suffix.size()>96||suffix.find_first_not_of(L"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-.")!=std::wstring::npos)return {};return suffix.empty()?name:name+L"."+suffix;}
std::wstring gateName(const std::wstring&suffix){auto name=pipeName(suffix);return name.empty()?L"":L"Local\\"+name.substr(9)+L".gate";}
std::wstring contextCapabilityName(const std::wstring&suffix){return gateName(suffix)+L".context-v2";}
std::wstring learningName(const std::wstring&suffix){return gateName(suffix)+L".learning-v1";}
CaptureEmitter::~CaptureEmitter(){{std::lock_guard<std::mutex>guard(lock);stopping=true;}wake.notify_one();if(worker.joinable())worker.join();}
void CaptureEmitter::start(){if(worker.joinable())return;try{std::atomic_store(&hostSource,std::make_shared<const CaptureContextWire>(sourceForCurrentHost()));pipe=pipeName(suffix);gate=gateName(suffix);if(!pipe.empty()&&!gate.empty())worker=std::thread([this]{run();});}catch(...){pipe.clear();gate.clear();}}
void CaptureEmitter::emit(std::wstring_view text,HWND hwnd,const std::array<unsigned char,16>&session,const std::array<unsigned char,16>&editor,bool normal,uint32_t layout,uint32_t field,bool paste)noexcept{if(!normal||text.empty())return;try{if(gate.empty())return;auto mapping=OpenFileMappingW(FILE_MAP_READ,FALSE,gate.c_str());if(!mapping)return;auto state=reinterpret_cast<const CaptureGate*>(MapViewOfFile(mapping,FILE_MAP_READ,0,0,sizeof(CaptureGate)));uint64_t generation=state&&state->enabled?uint64_t(state->generation):0;if(state)UnmapViewOfFile(state);CloseHandle(mapping);if(!generation)return;std::unique_lock<std::mutex>guard(lock,std::try_to_lock);if(!guard||pending.size()>=64||pendingBytes+(text.size()>120000?0:text.size()*sizeof(wchar_t))>2*1024*1024){++lost;return;}Packet packet;packet.header.kind=paste?8:1;auto original=std::atomic_load(&hostSource);if(original)packet.source=*original;packet.source.field=field<=6?field:0;packet.source.layout=layout<=2?layout:0;packet.header.generation=generation;packet.header.foreground=reinterpret_cast<uintptr_t>(hwnd);packet.header.observedTick=GetTickCount64();FILETIME stamp{};GetSystemTimeAsFileTime(&stamp);ULARGE_INTEGER stampValue{};stampValue.LowPart=stamp.dwLowDateTime;stampValue.HighPart=stamp.dwHighDateTime;packet.header.observedAt=(stampValue.QuadPart-116444736000000000ULL)/10000000ULL;packet.header.scope=1;packet.header.session=session;packet.header.editor=editor;if(text.size()>120000){if(paste)return;packet.header.kind=2;}else packet.text.assign(text);packet.header.utf16Count=uint32_t(packet.text.size());pendingBytes+=packet.text.size()*sizeof(wchar_t);pending.push_back(std::move(packet));guard.unlock();wake.notify_one();}catch(...){++lost;}}
void CaptureEmitter::emitLearning(std::wstring_view reading,std::wstring_view text,HWND hwnd,uint32_t kind)noexcept{if((kind!=3&&kind!=5&&kind!=6&&kind!=7)||reading.empty()||text.empty()||reading.size()>128||text.size()>1024||gate.empty())return;try{auto mapping=OpenFileMappingW(FILE_MAP_READ,FALSE,learningName(suffix).c_str());if(!mapping)return;auto state=static_cast<const LearningMapping*>(MapViewOfFile(mapping,FILE_MAP_READ,0,0,sizeof(LearningMapping)));auto generation=state&&state->version==1&&state->enabled?state->generation:0;if(state)UnmapViewOfFile(state);CloseHandle(mapping);if(!generation)return;std::unique_lock<std::mutex>guard(lock,std::try_to_lock);if(!guard||pending.size()>=64)return;Packet packet;packet.header.kind=kind;packet.header.scope=1;packet.header.generation=generation;packet.header.foreground=reinterpret_cast<uintptr_t>(hwnd);packet.header.observedTick=GetTickCount64();packet.text=std::wstring(reading)+wchar_t(31)+std::wstring(text);packet.header.utf16Count=uint32_t(packet.text.size());pendingBytes+=packet.text.size()*sizeof(wchar_t);pending.push_back(std::move(packet));guard.unlock();wake.notify_one();}catch(...) {}}
void CaptureEmitter::run()noexcept{try{std::atomic_store(&hostSource,std::make_shared<const CaptureContextWire>(sourceForCurrentHost(true)));auto name=pipe;if(name.empty())return;for(;;){Packet packet;{std::unique_lock<std::mutex>guard(lock);wake.wait(guard,[&]{return stopping||!pending.empty();});if(stopping)return;packet=std::move(pending.front());pendingBytes-=packet.text.size()*sizeof(wchar_t);pending.pop_front();}HANDLE pipe=CreateFileW(name.c_str(),GENERIC_WRITE,0,nullptr,OPEN_EXISTING,FILE_FLAG_OVERLAPPED,nullptr);if(pipe==INVALID_HANDLE_VALUE){++lost;continue;}bool metadata=false;if(packet.header.kind==8){HANDLE capability=OpenFileMappingW(FILE_MAP_READ,FALSE,(gate+L".paste-v1").c_str());if(!capability){CloseHandle(pipe);continue;}auto*v=static_cast<const DWORD*>(MapViewOfFile(capability,FILE_MAP_READ,0,0,sizeof(DWORD)));bool okay=v&&*v==1;if(v)UnmapViewOfFile(v);CloseHandle(capability);if(!okay){CloseHandle(pipe);continue;}metadata=true;}if(packet.header.kind<=2){HANDLE cap=OpenFileMappingW(FILE_MAP_READ,FALSE,contextCapabilityName(suffix).c_str());if(cap){auto*v=static_cast<const DWORD*>(MapViewOfFile(cap,FILE_MAP_READ,0,0,sizeof(DWORD)));metadata=v&&*v==2;if(v)UnmapViewOfFile(v);CloseHandle(cap);}}packet.header.version=metadata?2:1;auto loss=lost.exchange(0);if(loss){CaptureHeader gap=packet.header;gap.kind=packet.header.kind>=3?4:2;gap.utf16Count=0;gap.version=1;DWORD n=0;OVERLAPPED o{};o.hEvent=CreateEventW(nullptr,TRUE,FALSE,nullptr);BOOL ok=WriteFile(pipe,&gap,sizeof(gap),&n,&o);if(!ok&&GetLastError()==ERROR_IO_PENDING){if(WaitForSingleObject(o.hEvent,25)!=WAIT_OBJECT_0)CancelIoEx(pipe,&o);GetOverlappedResult(pipe,&o,&n,TRUE);}CloseHandle(o.hEvent);}std::string data(sizeof(packet.header)+packet.text.size()*sizeof(wchar_t)+(metadata?sizeof(CaptureContextWire):0),'\0');memcpy(data.data(),&packet.header,sizeof(packet.header));if(!packet.text.empty())memcpy(data.data()+sizeof(packet.header),packet.text.data(),packet.text.size()*sizeof(wchar_t));if(metadata)memcpy(data.data()+sizeof(packet.header)+packet.text.size()*sizeof(wchar_t),&packet.source,sizeof(packet.source));OVERLAPPED o{};o.hEvent=CreateEventW(nullptr,TRUE,FALSE,nullptr);DWORD n=0;BOOL ok=WriteFile(pipe,data.data(),DWORD(data.size()),&n,&o);if(!ok&&GetLastError()==ERROR_IO_PENDING){if(WaitForSingleObject(o.hEvent,25)!=WAIT_OBJECT_0)CancelIoEx(pipe,&o);ok=GetOverlappedResult(pipe,&o,&n,TRUE);}if(!ok||n!=data.size())++lost;CloseHandle(o.hEvent);CloseHandle(pipe);}}catch(...){}}
}
